-- Published EBSi historical TOP15 wrong-answer percentages, 2012–2015 calendar years.
begin;
create temp table ebsi_rates (session_id uuid, year integer, month integer, grade text, section text,
 n integer, rate numeric, level text, source_url text, paper_id integer, collected_at timestamptz,
 primary key(session_id,section,n)) on commit drop;
create temp table ebsi_matches on commit drop as
select p.id as problem_id,r.*
from ebsi_rates r
join public.exam_sessions s on (s.id,s.calendar_year,s.month,s.grade)=(r.session_id,r.year,r.month,r.grade)
join public.exam_questions q on (q.session_id,q.section,q.question_no)=(r.session_id,r.section,r.n) and q.variant='standard'
join public.problems p on p.exam_question_id=q.id and p.public and not p.withdrawn;
do $$begin
 if (select count(*) from ebsi_matches)<>1005 or
 (select count(distinct problem_id) from ebsi_matches)<>1005
 then raise exception 'EBSI_CATALOG_MATCH_INCOMPLETE'; end if;
end$$;
select problem_id,level,'correct_rate',rate,'ebsi-public-wrong-answer-top15',source_url,paper_id,collected_at,'ebsi-wrong-answer-top15-20-50-80-v1'
from ebsi_matches
on conflict(problem_id) do nothing;
do $$begin
 if exists(select 1 from ebsi_matches m left join public.problem_difficulties d using(problem_id) where d.problem_id is null)
 then raise exception 'EBSI_RATES_NOT_PERSISTED'; end if;
end$$;
select m.year,m.level,count(*) as matched,
 count(*) filter(where d.problem_id is null) as pending,
 count(*) filter(where (m.level,m.rate,m.source_url)=(d.level,d.correct_rate,d.source_url)) as imported,
 count(*) filter(where d.classification_method='manual') as manual
from ebsi_matches m left join public.problem_difficulties d using(problem_id)
group by m.year,m.level order by m.year,m.level;
commit;
